int lcs(const char* a, const char* b, int i, int j)
{
    // Base case: empty suffix → no common subsequence
    if (i == 0 || j == 0)
        return 0;

    // Characters match → extend LCS
    if (a[i - 1] == b[j - 1])
        return 1 + lcs(a, b, i - 1, j - 1);

    // Characters differ → choose the best of skipping either prefix
    return std::max(lcs(a, b, i - 1, j), lcs(a, b, i, j - 1));
}

