    std::vector<std::vector<int>> dp(n + 1, std::vector<int>(k + 1, 0));

    // Base case: choosing 0 elements from i elements is always 1.
    for (int i = 0; i <= n; ++i) {
        dp[i][0] = 1;
    }

    // Fill the table using the recurrence relation.
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= std::min(i, k); ++j) {
