void preorder(Node* node)
{
  if (node == nullptr)
    return;

  // Memoization table: key = (node, visited) where visited is a bitmask.
  // The bitmask indicates which children have been visited.
  std::unordered_map<std::pair<Node*, int>, bool> memo;

  auto visitNode = [&](Node* n) {
    visit(n->value);
  };

  auto dfs = [&](Node* n, int visited) -> bool {
    if (n == nullptr)
      return false;

    auto key = {n, visited};
    auto it = memo.find(key);
    if (it != memo.end())
      return it->second;

    bool result = true;
    if ((visited & 1) == 0) {
      visitNode(n);
      result &= dfs(n->left, visited | 1);
    }
    if ((visited & 2) == 0) {
      result &= dfs(n->right, visited | 2);
    }
    memo[key] = result;
    return result;
  };

  dfs(node, 0);
}

