void fill(int** grid, int row, int col, int from, int to)
{
  // Guard against invalid indices or non‑matching value.
  if (row < 0 || col < 0 || !grid || !grid[row] || grid[row][col] != from)
    return;

  // Replace the target cell with the replacement value.
  grid[row][col] = to;

  // Recursively fill the four adjacent cells.
  fill(grid, row + 1, col, from, to);
  fill(grid, row - 1, col, from, to);
  fill(grid, row, col + 1, from, to);
  fill(grid, row, col - 1, from, to);
}

