{
    // Base case: when the smallest element is zero, the product is 1.
    if (minimum == 0)
        return 1;

    // Base case: when the smallest element is negative or the maximum is zero,
    // the product is zero.
    if (minimum < 0 || maximum == 0)
        return 0;

    // Recursive case: compute the product for the current state and the next.
