int total(const char* count, const char* index, int result, int current)
{
    static std::unordered_map<std::pair<int,int>, int> memo;
    auto key = std::make_pair(result, current);
    auto it = memo.find(key);
    if (it != memo.end())
        return it->second;

    int res = 0;
    if (result == 0 || current == 0)
        res = 0;
    else if (count[result - 1] == index[current - 1])
        res = 1 + total(count, index, result - 1, current - 1);
    else
        res = std::max(total(count, index, result - 1, current), total(count, index, result, current - 1));

    memo[key] = res;
    return res;
}

