void total(int** count, int index, int result, int current, int limit)
{
  // Base case: if the current value already matches the limit, we are done.
  if (index < 0 || result < 0 || count[index][result] != current)
    return;

  // Mark the cell as fully filled.
  count[index][result] = limit;

  // Recurse over all four possible moves.
  for (int i = -1; i <= 1; ++i) {
    int nextIndex = index + i;
    if (nextIndex >= 0 && nextIndex < 10) { // Assuming a 10x10 grid for simplicity.
      for (int j = -1; j <= 1; ++j) {
        int nextResult = result + j;
        if (nextResult >= 0 && nextResult < 10) {
          total(count, nextIndex, nextResult, current, limit);
        }
      }
    }
  }
}

